delete
from act_hi_actinst
where task_id_ = #{taskId}
  and act_id_ = #{activityId}

mapper.select:
SELECT DISTINCT t.id_ AS taskId, t.name_ AS taskName, t.task_def_key_ AS activityId, t.assignee_ AS assigneeId, t.proc_inst_id_ AS procInsId, t.proc_def_id_ AS procDefId, t.create_time_ AS "createTime", pd.name_ AS procDefName, pd.key_ AS procDefKey, pd.category_ AS category, e.start_user_id_ AS startUserId, ext.current_name AS startUserName, 'todo' AS noticeType FROM act_ru_task t LEFT JOIN act_re_procdef pd ON pd.id_ = t.proc_def_id_ LEFT JOIN act_ru_execution e ON e.id_ = t.proc_inst_id_ LEFT JOIN act_ru_identitylink il ON il.task_id_ = t.id_ LEFT JOIN basicdb_flowable.tbl_flow_extend_procinst ext ON ext.proc_ins_id = t.proc_inst_id_
AND pd.category_ = #{category}
AND t.create_time_ >= #{params.beginTime}
AND t.create_time_ <= #{params.endTime}
AND ( t.assignee_ = #{userId} OR ( ( t.assignee_ IS NULL OR t.assignee_ = '' ) AND ( il.user_id_ = #{userId} OR il.group_id_ IN (SELECT sur.role_id::varchar FROM basicdb_flowable.sys_user_role sur LEFT JOIN basicdb_flowable.sys_user su ON su.user_id = sur.user_id WHERE su.user_id::varchar = #{userId}) ) ) )
ORDER BY t.create_time_ DESC

SELECT t.id_ AS taskId, t.name_ AS taskName, t.task_def_key_ AS activityId, t.assignee_ AS assigneeId, t.proc_inst_id_ AS procInsId, t.proc_def_id_ AS procDefId, t.start_time_ AS "createTime", t.end_time_ AS finishTime, pd.name_ AS procDefName, pd.key_ AS procDefKey, pd.category_ AS category, pi.start_user_id_ AS startUserId FROM act_hi_taskinst t LEFT JOIN act_re_procdef pd ON pd.id_ = t.proc_def_id_ LEFT JOIN act_hi_procinst pi ON pi.id_ = t.proc_inst_id_
t.end_time_ IS NOT NULL
and pd.key_ like '%' || #{processKey} || '%'
and pd.name_ like '%' || #{processName} || '%'
and t.proc_inst_id_ = #{procInsId}
and t.assignee_ = #{userId}
and pi.start_user_id_ = #{startUserId}
and to_char(t.start_time_,'yyyy-mm') = to_char(to_date(#{params.beginTime},'yyyy-mm'),'yyyy-mm')
and to_char(t.end_time_,'yyyy-mm') = to_char(to_date(#{params.endTime},'yyyy-mm'),'yyyy-mm')
and pd.category_ = #{category}
order by t.end_time_ desc

SELECT pi.id_ AS procInsId, pi.proc_def_id_ AS procDefId, pi.start_user_id_ AS startUserId, pi.start_time_ AS "createTime", pi.end_time_ AS finishTime, pd.name_ AS procDefName, pd.key_ AS procDefKey, pd.category_ AS category, CASE WHEN pi.end_time_ IS NULL THEN 'running' ELSE 'completed' END AS processStatus FROM act_hi_procinst pi LEFT JOIN act_re_procdef pd ON pd.id_ = pi.proc_def_id_
and pd.key_ = #{processKey}
and pd.name_ like '%' || #{processName} || '%'
and pi.end_time_ IS NULL and pi.end_time_ IS NOT NULL
and pd.category_ = #{category}
and pi.start_user_id_ = #{startUserId}
and pi.id_ = #{procInsId}
and to_char(pi.start_time_,'yyyy-mm') = to_char(to_date(#{params.beginTime},'yyyy-mm'),'yyyy-mm')
and to_char(coalesce(pi.end_time_, pi.start_time_),'yyyy-mm') = to_char(to_date(#{params.endTime},'yyyy-mm'),'yyyy-mm')
order by pi.start_time_ desc

select count(distinct t.id_)
from act_ru_task t
left join act_re_procdef pd on pd.id_ = t.proc_def_id_
left join act_ru_execution e on e.id_ = t.proc_inst_id_
left join act_ru_identitylink il on il.task_id_ = t.id_


    AND pd.category_ = #{category}


    AND t.create_time_ >= #{params.beginTime}


    AND t.create_time_ <= #{params.endTime}


    and ( t.assignee_ = #{userId}
          or ( ( t.assignee_ IS NULL OR t.assignee_ = '' )
               and ( il.user_id_ = #{userId}
                     or il.group_id_ in (
                        select sur.role_id::varchar from basicdb_flowable.sys_user_role sur
                        left join basicdb_flowable.sys_user su on su.user_id = sur.user_id
                        where su.user_id::varchar = #{userId}
                     ) ) ) )

select text_
from act_hi_varinst
where execution_id_ = #{executionId}
  and name_ = #{key}

select t1.id_ from act_hi_procinst t1 left join act_re_procdef t2 on t1.proc_def_id_ = t2.id_ where t1.end_time_ is null
and t2.category_ in
#{item}

